// -------- OPEN PROVIDER PACKS (PROPOSED EXTENSION FORMAT, DEMONSTRATION ONLY) --------
const codeExample=(s)=>`<pre class="spec-code">${esc(s)}</pre>`;
const evidenceManifest=`apiVersion: specbound.example/v1alpha1
kind: EvidenceProviderPack
metadata:
  id: org.acme.aws-network
  version: 1.4.2
  title: AWS Network Provider
runtime:
  kind: approved-container
  image: registry.example/evidence/aws-reader@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa
  entrypoint: ["/collector"]
  input: contracts/collect-request.json
  output: contracts/observation.json
  # Implementation can use cloud APIs or Terraform data sources.
capabilities:
  - id: net.internet-reachability
    version: v1
    outputSchema: schemas/reachability.json
permissions:
  aws:
    - rds:DescribeDBInstances
    - ec2:DescribeSecurityGroups
tests:
  - tests/reachability.yaml`;
const capabilitySchema=`{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Internet reachability result",
  "type": "object",
  "required": ["publicly_reachable"],
  "properties": {
    "publicly_reachable": { "type": "boolean" },
    "path_summary": { "type": "string" }
  },
  "additionalProperties": false
}`;
const sampleObservation=`kind: EvidenceObservation
subject: aws:rds:db-primary
capability: net.internet-reachability/v1
observation:
  publicly_reachable: true
  path_summary: "Internet → ingress 0.0.0.0/0"
observedAt: "2026-11-02T08:20:00Z"
provenance:
  providerPack: org.acme.aws-network
  release: v1.4.2
  sourceRevision: git:4f92b1c…
  target: customer-service@9d2e8f1
trust: verified-provider`;
function epCatalog(){return shell('ep-catalog',`${topTitle('PLATFORM / EXTENSIONS','Evidence Provider Packs','Git repositories describe how technical facts are collected. The evidence itself is generated when a check runs.',btn('+ Connect Git repo','ep-connect','blue'))}<div class="dash-row stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:15px">${stat('Connected provider packs','6','')}${stat('Available capabilities','24','')}${stat('Missing capability matches','2','')}${stat('Health alerts','1','',true)}</div><div class="table-card"><table class="tbl"><thead><tr><th>PROVIDER PACK</th><th>GIT REPOSITORY</th><th>RELEASE</th><th>CAPABILITIES</th><th>RUNTIME</th><th>STATUS</th></tr></thead><tbody>${[['AWS Network','acme/aws-network-provider','v1.4.2','net.internet-reachability/v1','approved container','Active'],['OpenAPI Inspector','acme/openapi-inspector','v0.8.1','api.auth-schema/v1','parser','Active'],['Cloud Inventory','acme/cloud-inventory','v1.2.0','cloud.resource-config/v1','sandbox runner','Active'],['K8s Workloads','acme/k8s-evidence','v1.1.0','k8s.workload-security/v1','trusted adapter','Draft']].map(r=>`<tr class="clickable" data-go="ep-manifest"><td><b>${r[0]}</b></td><td><span class="link">⑂ ${r[1]}</span></td><td><span class="code-chip">${r[2]}</span></td><td>${r[3]}</td><td>${r[4]}</td><td>${status(r[5],r[5]==='Active'?'green':'amber')}</td></tr>`).join('')}</tbody></table></div><div class="form-grid" style="margin-top:14px"><div class="panel"><h3>Pack categories</h3>${row('Governance Pack','Defines controls & expected outcomes')}${row('Evidence Provider Pack','Defines capability outputs & collection adapters')}${row('Observation','Generated evidence, not a Git Pack')}</div><div class="panel"><h3>Separation of concerns</h3><p class="caption">A governance rule requests <code>net.internet-reachability/v1</code>. Any trusted provider capable of producing conforming observations can satisfy the request. Policies never require AWS or Python specifically.</p>${btn('Connect provider pack →','ep-connect','small blue')}</div></div>`,'Providers / Evidence packs')}
function epConnect(){return shell('ep-connect',`${topTitle('PROVIDERS / CONNECT GIT','Connect an Evidence Provider Pack','Resolve a reviewed tag to a pinned revision. Configure credentials separately; never store credentials in the repo.')}${progress(['Connect repository','Validate manifest','Trust & activate'],0)}<div class="form-grid"><div class="panel"><h3>Source in Git</h3>${field('Repository',demo.providerRepo,'acme/aws-network-provider','providerRepo')}${selectField('Release tag',['v1.4.2','v1.4.1','v1.3.0'],demo.providerTag,'providerTag')}${row('Manifest file','<span class="code-chip">provider.yaml</span>')}${row('Release validation',status('Validated','green'))}${row('Pinned revision','<span class="code-chip">4f92b1c…</span>')}<div class="help-inline">Git supplies definitions and a pinned runtime reference. An organization administrator approves execution, credentials and outbound access. Terraform data source files, if used, belong to this pack, not the platform core.</div></div><div class="panel"><h3>Activation prerequisites</h3>${row('Approved runtime','pinned OCI collector image')}${row('Permission grant','AWS read-only role')}${row('Credential source','Organization connector')}${row('Capability contract','net.internet-reachability/v1')}${row('Pack test fixtures',status('4 passed','green'))}<div class="app-demo-notice"><b>Security boundary</b><br>Installing a provider cannot silently grant privileges. Organization admins review scopes, secrets and runtime isolation.</div></div></div>${backNext('ep-catalog','ep-manifest','Review manifest →')}`,'Providers / Connect pack')}
function epManifest(){return shell('ep-manifest',`${topTitle('PROVIDERS / AWS NETWORK','Provider manifest · provider.yaml','This is a proposed Git-native EvidenceProviderPack specification, not a built-in external standard.',status('Sample format','blue'))}<div class="git-info" style="grid-template-columns:1fr 1.25fr 1fr 1fr">${infoTag('PACK','org.acme.aws-network')}${infoTag('REPOSITORY','acme/aws-network-provider')}${infoTag('RELEASE','v1.4.2')}${infoTag('PINNED COMMIT','4f92b1c…')}</div><div class="spec-layout"><div class="panel"><div class="panelheader"><h3>provider.yaml</h3>${status('Declarative','blue')}</div>${codeExample(evidenceManifest)}</div><div><div class="panel"><h3>Repository structure</h3><div class="spec-tree">aws-network-provider/<br>├── provider.yaml<br>├── collector/ (optional HCL)<br>├── schemas/<br>│ &nbsp; └── reachability.json<br>├── tests/<br>│ &nbsp; └── reachability.yaml<br>└── README.md</div><p class="caption">A human or agent authors these files. The portal only validates and consumes released Git content.</p></div><div class="panel" style="margin-top:12px"><h3>Execution isolation</h3>${row('Runtime','approved collector container')}${row('Credentials','scoped secret reference')}${row('Provider result','typed observation')}<div class="app-demo-notice"><b>Pack-owned implementation</b><br><code>collector/main.tf</code> may use Terraform <code>data</code> blocks to query existing infrastructure. The core executes an approved collector through a generic runner interface; it contains no Terraform adapter.</div>${btn('View output contract →','ep-contract','small blue')}</div></div></div>`,'Providers / Manifest')}
function epContract(){return shell('ep-contract',`${topTitle('PROVIDERS / CAPABILITY','Capability contract and test cases','The schema defines what the provider produces; governance packs independently choose when it is sufficient.')}${progress(['Provider manifest','Capability schema','Generated observation'],1)}<div class="spec-layout"><div class="panel"><h3>schemas/reachability.json</h3>${codeExample(capabilitySchema)}</div><div><div class="panel"><h3>tests/reachability.yaml</h3>${codeExample(`cases:\n  - name: Public database\n    input: { public: true }\n    expected: { publicly_reachable: true }\n  - name: Private database\n    input: { public: false }\n    expected: { publicly_reachable: false }`)}</div><div class="panel" style="margin-top:12px"><h3>Referenced by governance</h3>${row('security-pack · SEC-NET-001','requires capability')}${row('architecture-pack · ARCH-004','reuses same evidence')}${row('Required result','publicly_reachable = false')}${btn('View governance manifest →','manifest-tab','small')}${btn('Inspect an observation →','ep-observation','small blue')}</div></div></div>`,'Providers / Contract')}
function epObservation(){return shell('ep-observation',`${topTitle('PROVIDERS / EVIDENCE','Collected observation','Actual records come from provider runs and are stored separately from versioned Git packs.',status('Verified','green'))}<div class="spec-layout"><div class="panel"><h3>Evidence record · evi-2026-0172</h3>${codeExample(sampleObservation)}</div><div><div class="panel"><h3>Pack vs observation</h3>${row('Pack in Git','Versioned collection method')}${row('Provider capability','Typed schema / contract')}${row('Evidence record','Observed product fact')}${row('Assessment','Pack evaluates that fact')}<div class="app-demo-notice"><b>Trust matters</b><br>A valid JSON schema does not prove the observation is true. The runtime identity, scope, collector implementation and freshness determine trust.</div></div><div class="panel" style="margin-top:12px"><h3>Consumers</h3>${row('SEC-NET-001',status('Fail','red'))}${row('ARCH-NET-004',status('Fail','red'))}${btn('Trace to finding →','finding','small blue')}</div></div></div>`,'Evidence / Observation')}
// -------- PR-SCOPED FINDINGS AND REMEDIATION --------

const prStep=()=>Math.max(0,Number(demo.prIteration)||0);
const prReport=()=>{const n=prStep();return {n,pass:n===0?38:n===1?39:41,fail:n===0?2:n===1?1:0,unknown:n<2?1:0,na:4,revision:n===0?'b27e921':n===1?'75c1a29':n===2?'c8419ab':`iteration-${n}`,outcome:n>=2?'Pass':'Fail'};};
function prComment(){const r=prReport();return `<div class="pr-gh-comment"><div class="gh-comment-top"><span class="gh-avatar">◇</span><b>specbound[bot]</b><span class="pill blue">GitHub App</span></div><div class="pr-gh-comment-body"><div class="pr-count-grid"><div><b>${r.pass}</b><span>Passed</span></div><div><b class="red-num">${r.fail}</b><span>Failed</span></div><div><b class="amber-num">${r.unknown}</b><span>Unknown</span></div><div><b>${r.na}</b><span>N/A</span></div></div><button class="pr-report-link" data-go="pr-findings">View governance report ↗</button></div></div>`;}

function prInbox(){return shell('pr-inbox',`${topTitle('DEVELOPMENT / PULL REQUEST','A pull request is opened','The author can be a human or an AI agent. Governance never assigns a developer or orchestrates a fix.',status('GitHub App','green'))}<div class="git-info" style="grid-template-columns:repeat(4,1fr)">${infoTag('REPOSITORY','acme/customer-service')}${infoTag('PULL REQUEST','#482')}${infoTag('AUTHOR','@dev-alex or agent identity')}${infoTag('TARGET','main')}</div><div class="form-grid" style="grid-template-columns:1.1fr .9fr"><div class="panel"><h3>GitHub · customer-service #482</h3><div class="pr-gh-header">⑂ &nbsp;<b>Prepare new RDS integration test</b> ${status('Open','green')}</div><p class="caption">Source: feat/rds-test → main · Changes in infrastructure and service configuration.</p><div class="code-diff"><div class="line-plus">+ publicly_accessible = true</div><div class="line-plus">+ cidr_blocks = ["0.0.0.0/0"]</div></div><div class="help-inline">A push or PR update triggers a webhook. The external collector analyzes the proposed commit and sends only the check outcome back to GitHub.</div>${btn('Open automated PR comment →','pr-check','blue')}</div><div class="panel"><h3>Independent roles</h3>${row('GitHub user / agent','Creates and updates the PR')}${row('Specbound','Runs assessment; posts counts + link')}${row('Product owner','Decides how the code is changed')}${row('Merge policy','Required check status (optional)')}<div class="app-demo-notice"><b>No dispatch</b><br>The platform never selects an agent, assigns remediation, or edits the code. Any authorized contributor can use the same report.</div></div></div>`,'Pull Requests / Created')}

function prCheck(){return shell('pr-check',`${topTitle('PULL REQUESTS / #482','A compact PR comment','The GitHub comment contains only the four counts and a single link. No findings, file annotations or instructions.',status('Check: failure','red'))}<div class="form-grid" style="grid-template-columns:1.12fr .88fr"><div class="panel"><h3>GitHub · PR #482 · Conversation</h3>${prComment()}<div class="help-inline">The GitHub App creates one identifiable issue comment for this PR and <b>edits the same comment</b> on every new push. Old revisions remain available in the portal.</div></div><div class="panel"><h3>Separate merge gate</h3>${row('Specbound / Governance',status(prReport().outcome,prReport().outcome==='Pass'?'green':'red'))}${row('Checked revision',`<span class="code-chip">${prReport().revision}</span>`)}${row('PR comment','Numbers + report link only')}${row('Result details','Portal only')}<div class="app-demo-notice">A comment informs people and agents. A separate required GitHub status check gates merging on the exact latest commit.</div>${btn('Open linked report →','pr-findings','small blue')}</div></div>`,'PR #482 / Comment')}

function prFindings(){const r=prReport();return shell('pr-findings',`${topTitle('PR #482 / GOVERNANCE REPORT','Detailed assessment in the portal','The PR comment links here. Only the portal shows controls, evidence, affected resources, and explanations.',status(r.outcome,r.outcome==='Pass'?'green':'red'))}<div class="git-info" style="grid-template-columns:repeat(4,1fr)">${infoTag('CONTEXT','Pull request')}${infoTag('TARGET REVISION',r.revision)}${infoTag('PACK','security-pack v1.2.0')}${infoTag('EVIDENCE','Source configuration scan')}</div><div class="form-grid" style="grid-template-columns:1.17fr .83fr"><div class="panel"><div class="panelheader"><h3>Findings for this commit</h3>${status(r.fail+' failed',r.fail?'red':'green')}</div>${r.fail?`${row('SEC-NET-001 · RDS public access flag',status('Fail','red'))}${r.fail>1?row('SEC-NET-002 · Broad ingress CIDR',status('Fail','red')):''}`:row('No violating controls',status('Pass','green'))}${r.unknown?row('Missing network reachability evidence',status('Unknown','amber')):''}<div class="divider"></div><h3>Traceability · SEC-NET-001</h3><div class="chain">${[['Control','SEC-NET-001'],['Capability','iac.config-access/v1'],['Collector','Git Config Scanner'],['Observation',r.fail?'true':'false'],['Decision',r.outcome]].map((v,i)=>`${i?'<span class="arr">›</span>':''}<div class="chain-step"><b>${v[0]}</b><small>${v[1]}</small></div>`).join('')}</div><div class="code-diff"><div class="line-minus">infra/database.tf · proposed configuration</div><div class="line-plus">+ publicly_accessible = ${r.fail?'true':'false'}</div></div><p class="caption">Repository settings are not proof of live Internet reachability. Production assessment requires independent infrastructure observations.</p></div><div class="panel"><h3>What the report provides</h3>${row('Affected resource','aws_db_instance.customer')}${row('Observation source','Git source configuration')}${row('Control source','security-pack v1.2.0')}${row('Tested scope','Proposed PR configuration')}${row('Production status','Not evaluated here')}<div class="app-demo-notice"><b>Who fixes the code?</b><br>Anyone with Git permissions: human or AI agent. The portal only explains the violation. No agent-selection or dispatch functionality.</div>${btn('Continue to push / recheck →','pr-dispatch','small blue')}</div></div>`,'PR #482 / Portal report')}

function prDispatch(){const r=prReport();let hist=[];for(let n=0;n<=Math.min(r.n,6);n++){let fail=n===0?2:n===1?1:0;hist.push(`<tr><td><b>${n===0?'Initial PR':`Push ${n}`}</b></td><td><span class="code-chip">${n===0?'b27e921':n===1?'75c1a29':n===2?'c8419ab':`iteration-${n}`}</span></td><td>${status(fail?'Fail':'Pass',fail?'red':'green')}</td><td>${fail?'Fix and push again':'Ready for review'}</td></tr>`)}return shell('pr-dispatch',`${topTitle('PULL REQUESTS / #482 / LOOP','Push → analyze → comment → repeat','Each new commit re-evaluates independently. The author stays in Git, whether human or agent.',status('Iteration '+(r.n+1),'blue'))}<div class="form-grid" style="grid-template-columns:1.06fr .94fr"><div class="panel"><h3>Simulation: new commit pushed</h3><div class="resolution-flow">${[['Git push',r.revision],['Webhook','Received'],['Assessment',r.outcome],['Comment','Updated']].map((a,i)=>`<div class="res-step"><span class="res-tick">${i+1}</span><b>${a[0]}</b><small>${a[1]}</small></div>`).join('')}</div><div class="table-card" style="margin-top:13px"><table class="tbl"><thead><tr><th>ROUND</th><th>COMMIT</th><th>RESULT</th><th>NEXT</th></tr></thead><tbody>${hist.reverse().join('')}</tbody></table></div><div class="help-inline">Old results stay linked to their SHA; only the latest valid SHA controls the PR gate. Stale/out-of-order webhook runs must never overwrite newer results.</div><div style="display:flex;gap:9px;margin-top:13px">${btn('Simulate next push + recheck →','pr-push','blue')}${btn('Restart demonstration','pr-reset','small')}</div></div><div class="panel"><h3>Same GitHub comment · updated</h3>${prComment()}${row('Latest assessed revision',`<span class="code-chip">${r.revision}</span>`)}${row('Merge status',status(r.outcome,r.outcome==='Pass'?'green':'red'))}<div class="app-demo-notice">The button simulates a Git push and automated check. It does <b>not</b> dispatch work to an agent or make a Git request.</div>${btn('Inspect final review state →','pr-green','small blue')}</div></div>`,'PR #482 / Repeat cycle')}

function prGreen(){const r=prReport();return shell('pr-green',`${topTitle('PULL REQUESTS / #482 / REVIEW','Latest revision passes','After enough fixes, the same PR comment shows zero failed and zero unknown controls. Human review and post-deployment checks remain separate.',status('Ready for review','green'))}<div class="form-grid" style="grid-template-columns:1fr 1fr"><div class="panel"><h3>Illustrative passing revision · c8419ab</h3><div class="code-diff"><div class="line-minus">− publicly_accessible = true</div><div class="line-plus">+ publicly_accessible = false</div><div class="line-minus">− cidr_blocks = ["0.0.0.0/0"]</div><div class="line-plus">+ cidr_blocks = ["10.42.0.0/16"]</div></div>${row('Commit author','Human or AI agent')}${row('Required governance check',status('Pass','green'))}${row('Code review','Separate repository rules')}${row('Actual production evidence',status('Not yet collected','amber'))}${btn('Repeat another push →','pr-dispatch','small')}</div><div class="panel"><h3>GitHub · single updated comment</h3><div class="pr-gh-comment"><div class="gh-comment-top"><span class="gh-avatar">◇</span><b>specbound[bot]</b></div><div class="pr-gh-comment-body"><div class="pr-count-grid"><div><b>41</b><span>Passed</span></div><div><b class="red-num">0</b><span>Failed</span></div><div><b class="amber-num">0</b><span>Unknown</span></div><div><b>4</b><span>N/A</span></div></div><button class="pr-report-link" data-go="pr-findings">View governance report ↗</button></div></div><div class="app-demo-notice"><b>Version-specific</b><br>Passing a proposed commit does not certify deployed infrastructure. Runtime evidence and findings have their own assessment context.</div>${btn('See baseline findings →','change-inbox','small blue')}</div></div>`,'PR #482 / Passed')}

function changeReleases(){return shell('change-releases',`${topTitle('GOVERNANCE / RELEASES','New governance version detected','A reviewed pack release changes the required controls for already deployed products.',status('New release','blue'))}<div class="git-info" style="grid-template-columns:repeat(4,1fr)">${infoTag('PACK','security-pack')}${infoTag('CURRENT','v1.2.0')}${infoTag('CANDIDATE','v1.3.0')}${infoTag('SOURCE','Git tag → pinned SHA')}</div><div class="form-grid"><div class="panel"><h3>Changes in v1.3.0</h3>${row('SEC-NET-001','Broader database reachability scope')}${row('SEC-LOG-007','New privileged action audit check')}${row('SEC-EXP-002','New external API policy')}${row('Controls added','2')}${row('Controls modified','1')}<div class="help-inline">A source repo release does not automatically rewrite the product. The organization chooses if and when the new pack is active.</div></div><div class="panel"><h3>Change events</h3>${row('Tag v1.3.0 discovered','09:20 UTC')}${row('Manifest validated',status('Pass','green'))}${row('Signer verified',status('Pass','green'))}${row('Impact simulation',status('Not started','amber'))}${btn('Simulate on baseline →','change-impact','blue')}</div></div>`,'Governance / Release discovery')}
function changeImpact(){return shell('change-impact',`${topTitle('GOVERNANCE / RELEASE IMPACT','Impact on deployed products','Re-evaluate the registered production baseline with the candidate controls before enforcement.',status('Simulation','blue'))}<div class="dash-row stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">${stat('Products in scope','12','')}${stat('New baseline failures','7','',true)}${stat('New unknowns','3','',true)}${stat('Unaffected','2','')}</div><div class="table-card"><table class="tbl"><thead><tr><th>PRODUCT</th><th>DEPLOYMENT</th><th>OLD PACK</th><th>NEW PACK</th><th>REASON</th></tr></thead><tbody>${[['customer-service','prod · 9d2e8f1','Pass','Fail','SEC-LOG-007'],['billing-api','prod · 4cb11d3','Pass','Fail','SEC-EXP-002'],['consent-service','prod · 6b4a229','Pass','Unknown','No capability provider'],['web-portal','prod · 9f3a221','Pass','Pass','Not affected']].map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${status(r[2])}</td><td>${status(r[3])}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table></div><div class="form-grid" style="margin-top:15px"><div class="panel"><h3>Choose rollout</h3>${row('Simulate only',status('Non-blocking','blue'))}${row('Staged enforcement','Teams / dates')}${row('Activate release','New baseline evaluations')}${btn('Inspect resulting findings →','change-inbox','small blue')}</div><div class="panel"><h3>Assessment scope</h3><p class="caption">Evaluations must use the last known deployed revision and current observed environment. Missing providers remain UNKNOWN, not PASS. A new regulation may create findings without any code PR.</p></div></div>`,'Governance / Simulation')}
function changeInbox(){return shell('change-inbox',`${topTitle('FINDINGS / INBOX','Findings · different origins, one model','PR findings are tied to proposed commits. Baseline findings are tied to deployed products and the policy version.',btn('PR checks →','pr-inbox','blue'))}<div class="dash-row stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:14px">${stat('All open','37','')}${stat('New governance release','7','')}${stat('PR-scoped','4','')}${stat('Runtime / drift','26','')}</div><div class="filterbar"><div class="filter">Origin: All ⌄</div><div class="filter">State: Open ⌄</div><div class="filter">Team: All ⌄</div><div class="filter">⌕ Search findings…</div></div><div class="table-card"><table class="tbl"><thead><tr><th>FINDING</th><th>ORIGIN</th><th>SUBJECT / REVISION</th><th>CONTROL</th><th>STATE</th><th>OWNER</th></tr></thead><tbody><tr class="clickable" data-go="change-triage"><td><b class="link">FND-881 · Audit logs missing</b></td><td>${status('Policy update','blue')}</td><td>customer-service · prod</td><td>SEC-LOG-007</td><td>${status('Open','red')}</td><td>Customer Platform</td></tr><tr class="clickable" data-go="pr-findings"><td><b class="link">PRF-482-01 · Public DB ingress</b></td><td>${status('Pull request','blue')}</td><td>PR #482 · b27e921</td><td>SEC-NET-001</td><td>${status('Fail','red')}</td><td>Customer Platform</td></tr><tr class="clickable" data-go="finding"><td><b class="link">FND-7621 · DB publicly reachable</b></td><td>${status('Runtime drift','amber')}</td><td>customer-service · deployed</td><td>SEC-NET-001</td><td>${status('Open','red')}</td><td>Customer Platform</td></tr></tbody></table></div><div class="help-inline"><b>Finding identity:</b> (control, resource, evaluation context, baseline or PR revision) plus occurrence tracking. A policy-version change can create a new assessment without duplicating the same underlying issue.</div>${nextCard('Triage the new baseline finding','The governance pack changed, not the product code. The owning team receives an actionable control reference and evidence gaps.','change-triage','Assign remediation →')}`,'Findings / Inbox')}
function changeTriage(){return shell('change-triage',`${topTitle('FINDINGS / FND-881','New requirement · audit logging','SEC-LOG-007 became applicable after security-pack v1.3.0 was activated.',status('Open · baseline','red'))}<div class="git-info" style="grid-template-columns:repeat(4,1fr)">${infoTag('TRIGGER','Governance release')}${infoTag('PRODUCT','customer-service')}${infoTag('TEAM','Customer Platform')}${infoTag('RULE','SEC-LOG-007')}</div><div class="form-grid"><div class="panel"><h3>Why did this appear?</h3>${row('Earlier baseline','security-pack v1.2.0 → not applicable')}${row('New baseline','security-pack v1.3.0 → required')}${row('Evidence provider','AWS audit logs connector')}${row('Observation','privileged_action_logging = false')}${row('Evaluation','Deployed product · not a PR')}<div class="app-demo-notice">Trace: release v1.3.0 → new control SEC-LOG-007 → target production resource → observed evidence → finding FND-881.</div></div><div class="panel"><h3>Remediation assignment</h3>${row('Owning team','Customer Platform')}${row('Fix author','Any authorized human or AI agent')}${row('Target','Create normal remediation PR')}${row('Validation','PR checks then runtime evidence')}${row('Exception handling','Explicit expiry + approval')}${btn(demo.changeAssigned?'✓ Assigned to team':'Assign to owning team (demo)','change-assign','blue')}<p class="caption">A PR resolves the proposed code change; the baseline finding closes only after actual deployed evidence passes.</p>${btn('Follow to closure →','change-closed','small')}</div></div>`,'Findings / Assignment')}
function changeClosed(){return shell('change-closed',`${topTitle('FINDINGS / FND-881 / RESOLUTION','Baseline finding verified as fixed','After PR approval and deployment, the provider re-observes the live environment and closes the original baseline finding.',status('Resolved','green'))}<div class="panel"><div class="resolution-flow">${[['Policy updated','v1.3.0'],['Finding created','FND-881'],['PR deployed','#517'],['Live evidence passes','EVI-2026-0191']].map(r=>`<div class="res-step"><span class="res-tick">✓</span><b>${r[0]}</b><small>${r[1]}</small></div>`).join('')}</div></div><div class="resolved-columns" style="margin-top:13px"><div class="panel"><h3>Deployed evidence</h3>${row('Environment','Production')}${row('Deployment revision','<span class="code-chip">a420b77</span>')}${row('Control release','security-pack@v1.3.0')}${row('Capability','cloud.audit-logging/v1')}${row('Observed','privileged_action_logging: true')}${row('Freshness',status('Verified · current','green'))}</div><div class="panel"><h3>Finding lifetime</h3>${row('Original baseline finding','FND-881')}${row('Origin','Policy release change')}${row('PR resolution','#517 · merged')}${row('Production check',status('Pass','green'))}<div class="app-demo-notice"><b>No premature closure</b><br>A passing PR check does not close a production finding. Closure requires a matching live observation and reproducible assessment.</div>${btn('Open findings inbox →','change-inbox','small blue')}</div></div>`,'Findings / Verified closure')}
// -------- FIRST-CLASS AGENT ACCOUNTS IN TEAMS --------
function agentList(){return shell('agent-list',`${topTitle('ORGANIZATION / IDENTITIES','AI Agent Accounts','Each agent is a distinct nonhuman principal, optionally a member of multiple teams, with individual audit history.',btn('+ Register agent','agent-create','blue'))}<div class="dash-row stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">${stat('Active agents','7','')}${stat('Teams with agents','4','')}${stat('PRs proposed this week','16','')}${stat('Policy violations','0','')}</div><div class="table-card"><table class="tbl"><thead><tr><th>AGENT IDENTITY</th><th>TEAMS</th><th>INTEGRATION</th><th>ROLE</th><th>STATUS</th><th>LAST ACTION</th></tr></thead><tbody>${[['✦ Customer Fix Agent','Customer Platform · Billing Systems','GitHub App + OIDC','PR proposer','Active','09:42'],['✦ Security Refactor Agent','Architecture Enablement','External runner + OIDC','PR proposer','Active','Yesterday'],['✦ Audit Assistant','Customer Platform','Read-only integration','Viewer','Active','Yesterday']].map(r=>`<tr class="clickable" data-go="agent-scope">${r.map((v,i)=>`<td>${i===4?status(v,'green'):i===0?'<b class="link">'+v+'</b>':v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="help-inline"><b>Model:</b> Agents are team members, not shared team credentials. One identity can join multiple teams. A team role and an explicit execution scope are both needed to act.</div>${nextCard('Add a new agent account','Register its external machine identity, add it to teams, then authorize exactly which PR operations are permitted.','agent-create','Register agent →')}`,'Organization / Agents')}
function agentCreate(){return shell('agent-create',`${topTitle('AGENTS / CREATE','Register an AI agent identity','The portal records an optional nonhuman principal, not an embedded LLM, code-running agent or shared API token.')}${progress(['Identity','Team membership','Permissions & trust'],0)}<div class="form-grid"><div class="panel"><h3>Agent identity</h3>${field('Display name',demo.agentName,'Customer Fix Agent','agentName')}${field('Machine ID',demo.agentSlug,'customer-fix-agent','agentSlug')}${selectField('Integration',['GitHub App + OIDC','External worker + OIDC','Read-only connector'],demo.agentConnector,'agentConnector')}${row('Principal type','Nonhuman / agent')}${row('Account owner','Platform Automation')}<div class="help-inline">Agent credentials remain external. An account here is an optional governance identity mapping; Git identity and short-lived tokens are managed by the source platform.</div></div><div class="panel"><h3>Why a dedicated identity?</h3>${row('Attribution','Agent-originated PR commits attributed to agent ID')}${row('Revocation','Disable this agent without impacting humans')}${row('Limits','Teams + repos + permitted operations')}${row('Approvals','Human reviewer required where configured')}<div class="app-demo-notice"><b>Separation of duties</b><br>An agent must not approve its own pull requests, modify its own authorization or change governance pack releases.</div></div></div>${backNext('agent-list','agent-team','Assign team membership →')}`,'Agents / Identity')}
function agentTeam(){return shell('agent-team',`${topTitle('AGENTS / MEMBERSHIP','Add agent to teams','Agents appear in the same team membership model as humans, while their nonhuman type remains visible.')}${progress(['Identity','Team membership','Permissions & trust'],1)}<div class="form-grid"><div class="panel"><h3>Team membership</h3><div class="team-user"><span class="person">✦</span><div class="grow"><b>${esc(demo.agentName)}</b><small>agent/${esc(demo.agentSlug)}</small></div>${status('Agent','blue')}</div>${row('Customer Platform',status('PR proposer','blue'))}${row('Billing Systems',status('PR proposer','blue'))}${row('Architecture Enablement',status('Not a member',''))}<div class="help-inline">A team can have several AI agents. An agent can join several teams. Team membership alone never grants repository credentials.</div>${btn('Open Customer Platform →','team-detail','small')}</div><div class="panel"><h3>Working in Git</h3>${row('Customer Platform','Agent may contribute to selected repos')}${row('Billing Systems','Agent may contribute to selected repos')}${row('Specbound','Never dispatches tasks')}${row('PR assessments','Same workflow as human authors')}<div class="app-demo-notice">Membership defines team responsibility, not automated finding assignment. Agent tools and coding workflows run outside Specbound.</div>${btn('Review permissions →','agent-scope','blue')}</div></div>`,'Agents / Teams')}
function agentScope(){return shell('agent-scope',`${topTitle('AGENTS / SCOPES','Agent permission boundaries','Define what an agent can read, propose and never do. Human or delegated reviewers retain merge authority.')}${progress(['Identity','Team membership','Permissions & trust'],2)}<div class="form-grid" style="grid-template-columns:1.05fr .95fr"><div class="panel"><h3>Granted actions</h3>${row('Read permitted assessment reports',status('Allow','green'))}${row('Read selected source repositories',status('Allow','green'))}${row('Create branch / update own PR',status('Allow','green'))}${row('Request check re-run',status('Allow','green'))}${row('Approve own PR',status('Deny','red'))}${row('Merge protected branch',status('Deny','red'))}${row('Edit governance packs',status('Deny','red'))}${row('Write production cloud resources',status('Deny','red'))}<div class="help-inline">All permissions are intersected with repo permissions, selected team membership and environment policies.</div></div><div><div class="panel"><h3>Trust & safeguards</h3>${row('Identity','GitHub App + federated OIDC')}${row('Token lifetime','Short-lived')}${row('Allowed repositories','customer-service · billing-api')}${row('Finding assignment','Not supported in Specbound')}${row('Reviewer policy','Human code approval')}${row('Audit attribution','Agent principal + task ID')}</div><div class="panel" style="margin-top:13px"><h3>Activation</h3><p class="caption">Registering an agent does not start it or grant automatic access. Execution uses an external runner with a separately authorized integration.</p>${btn('View agent activity →','agent-history','blue')}</div></div></div>`,'Agents / Guardrails')}
function agentHistory(){return shell('agent-history',`${topTitle('AGENTS / CUSTOMER FIX AGENT','Agent execution & audit trail','Review the Git author identity, team, commit, pull request and independent assessment result.',status('Active identity','green'))}<div class="git-info" style="grid-template-columns:repeat(4,1fr)">${infoTag('IDENTITY','agent/customer-fix-agent')}${infoTag('TEAMS','Customer · Billing')}${infoTag('TRUST','Federated OIDC')}${infoTag('REVIEW POLICY','Human approval')}</div><div class="table-card"><table class="tbl"><thead><tr><th>TIME</th><th>EVENT</th><th>PRODUCT</th><th>GIT EVENT / PR</th><th>RESULT</th></tr></thead><tbody>${[['09:42','Checks passed after fix','customer-service','PR #482 · c8419ab','Pass'],['09:38','Proposed fix commit','customer-service','PR #482 · c8419ab','Created'],['09:32','Opened pull request','customer-service','PR #482','Created'],['Yesterday','Suggested change','billing-api','PR #511','Pass']].map(r=>`<tr class="clickable" data-go="pr-check"><td>${r[0]}</td><td><b>${r[1]}</b></td><td>${r[2]}</td><td>${r[3]}</td><td>${status(r[4],r[4]==='Pass'?'green':'blue')}</td></tr>`).join('')}</tbody></table></div><div class="form-grid" style="margin-top:13px"><div class="panel"><h3>Responsibility</h3>${row('Agent executed','Code proposal / PR')}${row('Owning team','Customer Platform')}${row('Code review','Human / separate approver')}${row('Compliance evaluation','Platform check runner')}</div><div class="panel"><h3>Operating principle</h3><p class="caption">The portal records external agent identities when connected but never dispatches coding tasks. Humans and agents work in Git, and the same independent checks respond to every new commit.</p>${btn('Inspect PR flow →','pr-inbox','small blue')}</div></div>`,'Agents / Activity')}


const renders={workspace,teams,'team-create':teamCreate,'team-members':teamMembers,'team-detail':teamDetail,products,'product-create':productCreate,'product-repository':productRepository,'product-discovery':productDiscovery,'product-detail':productDetail,packs,'pack-connect':packConnect,'pack-detail':packDetail,impact,'pack-activation':packActivation,overview,finding,'evidence-detail':evidenceDetail,remediation,resolution,providers,'provider-detail':providerDetail,'evidence-register':evidenceRegister,'docs-screen':docsScreen,'ep-catalog':epCatalog,'ep-connect':epConnect,'ep-manifest':epManifest,'ep-contract':epContract,'ep-observation':epObservation,'pr-inbox':prInbox,'pr-check':prCheck,'pr-findings':prFindings,'pr-dispatch':prDispatch,'pr-green':prGreen,'change-releases':changeReleases,'change-impact':changeImpact,'change-inbox':changeInbox,'change-triage':changeTriage,'change-closed':changeClosed,'agent-list':agentList,'agent-create':agentCreate,'agent-team':agentTeam,'agent-scope':agentScope,'agent-history':agentHistory};
function renderScreen(id){return (renders[id]||overview)()}
